-- Seed: the 49 verified Sudanese schools & centres in Greater Cairo (2025/2026)
-- Generated from INITIAL_SCHOOLS in index.html. Run after schema.sql. Safe to re-run (skips existing ids).
on conflict (id) do nothing;

-- Keep the id counter ahead of the seeded ids
select setval(pg_get_serial_sequence('public.schools', 'id'), (select max(id) from public.schools));
